// D-321: generate the HOST part of the learning bridge as plain browser JavaScript — no build tool.
//
//   node tools/laerligverse/generate-host-bridge.mjs           write the generated files under laerligverse/host/
//   node tools/laerligverse/generate-host-bridge.mjs --check   exit 1 if a committed file differs
//
// Source of truth stays TypeScript (adventure-engine/packages/learning-bridge/src). Node's built-in
// module.stripTypeScriptTypes (strip mode) erases the types — the sources use only erasable syntax — and
// relative ".ts" specifiers become ".js". The output is deterministic (no timestamps), so the --check drift
// test (tests/unit/laerligverse-host.test.mjs) compares byte for byte.
//
// Host files (bridge/): protocol, service, host, laerlig-service, index. NOT among them: client.ts (the
// game's end) and test-service.ts (the test adapter).
// Local didactic demo files (bridge/test-service.js, dev/): the TEST ADAPTER and Arkivskabet's curated
// items. tools/laerligverse/host-page.mjs serves them ONLY for `serve-local --backend=test-adapter` —
// never in the isolated test and never in a real page.
// The folder laerligverse/ is NOT in the deploy allowlist (tools/cloudflare-build-static.mjs).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import { stripTypeScriptTypes } from "node:module";

const HERE = dirname(fileURLToPath(import.meta.url));
export const REPO = resolve(HERE, "..", "..");
export const HOST_ROOT = join(REPO, "laerligverse", "host");
const LB = ["adventure-engine", "packages", "learning-bridge", "src"];

/** Every generated file: path under laerligverse/host/ → its source. */
export const OUTPUTS = Object.freeze([
  { to: "bridge/protocol.js", from: [...LB, "protocol.ts"], dev: false },
  { to: "bridge/service.js", from: [...LB, "service.ts"], dev: false },
  { to: "bridge/host.js", from: [...LB, "host.ts"], dev: false },
  { to: "bridge/laerlig-service.js", from: [...LB, "laerlig-service.ts"], dev: false },
  { to: "bridge/test-service.js", from: [...LB, "test-service.ts"], dev: true },
  { to: "dev/archive-items.js", from: ["adventure-engine", "packages", "archive-prototype", "src", "host-items.ts"], dev: true },
]);

export const INDEX = `// GENERATED by tools/laerligverse/generate-host-bridge.mjs — do not edit.
// The host part of laerligverse.bridge/2 for a no-build page.
export * from "./protocol.js";
export * from "./service.js";
export { BridgeHost } from "./host.js";
export { LaerligTaskService, createLaerligTaskService, DEFAULT_FLAGS } from "./laerlig-service.js";
`;

export const DEV_ADAPTER = `// GENERATED by tools/laerligverse/generate-host-bridge.mjs — do not edit.
// LOCAL DIDACTIC DEMO ONLY: the TEST ADAPTER (not Lærlig's server) with Arkivskabet's curated items.
export { FakeTaskService } from "../bridge/test-service.js";
export { ARCHIVE_ITEMS } from "./archive-items.js";
`;

/** Pure: one TypeScript module → browser JavaScript. Throws on anything a no-build page could not load. */
export function generateModule(source, from, { dev = false } = {}) {
  const js = stripTypeScriptTypes(source, { mode: "strip" });
  const rewritten = js
    .replace(/(from\s+["'])(\.\.?\/[^"']+)\.ts(["'])/g, "$1$2.js$3")
    .replace(/(import\s*\(\s*["'])(\.\.?\/[^"']+)\.ts(["']\s*\))/g, "$1$2.js$3");
  const code = rewritten.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
  if (/\bfrom\s+["'](?!\.)/.test(code)) throw new Error(`${from}: bare import found (a no-build page has no import map for it)`);
  if (/["'][^"']*\.ts["']/.test(code)) throw new Error(`${from}: a .ts specifier survived`);
  if (!dev && /test-service|client\.js/.test(code)) throw new Error(`${from}: imports the test adapter or the game end`);
  const sha = createHash("sha256").update(source).digest("hex");
  return `// GENERATED by tools/laerligverse/generate-host-bridge.mjs from ${from}\n// (source sha256 ${sha}). Do not edit: change the TypeScript source and regenerate.\n${rewritten}`;
}

/** All generated files as { path under laerligverse/host/ → content }. */
export function generateAll() {
  const out = {};
  for (const o of OUTPUTS) {
    const source = readFileSync(join(REPO, ...o.from), "utf8").split("\r\n").join("\n");
    out[o.to] = generateModule(source, o.from.join("/"), { dev: o.dev });
  }
  out["bridge/index.js"] = INDEX;
  out["dev/test-adapter.js"] = DEV_ADAPTER;
  return out;
}

/** Paths whose committed file differs from a fresh generation (empty = no drift). */
export function drift(root = HOST_ROOT) {
  const want = generateAll();
  return Object.keys(want).filter((f) => {
    const p = join(root, f);
    return !existsSync(p) || readFileSync(p, "utf8").split("\r\n").join("\n") !== want[f];
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes("--check")) {
    const d = drift();
    if (d.length > 0) {
      console.error(`laerligverse host: generated files out of date: ${d.join(", ")} — run node tools/laerligverse/generate-host-bridge.mjs`);
      process.exit(1);
    }
    console.log("laerligverse host: no drift");
  } else {
    const all = generateAll();
    for (const [f, content] of Object.entries(all)) {
      mkdirSync(dirname(join(HOST_ROOT, f)), { recursive: true });
      writeFileSync(join(HOST_ROOT, f), content);
    }
    console.log(`generated ${Object.keys(all).length} files under laerligverse/host/`);
  }
}
